import { TemplateRepository } from 'app/features/template/template/repository/template-repository.service';
import { Template } from 'app/features/template/template/model/template.model';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';
import { Component, inject } from '@angular/core';

@Component({ selector: 'template-view-enable-action', standalone: false, template: '' })
export class TemplateViewEnableActionComponent extends ConfirmAction<Template> {
  readonly name = 'enable';
  protected readonly scope = 'template/template';
  protected readonly repository = inject(TemplateRepository);

  protected override appliesTo(items: Template[]) {
    return items.every((item) => !item.enabled) && true;
  }
  protected execute([item]: Template[]) {
    return this.repository.enable(item.uid);
  }
}
